insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-bigvita-scalp-serum-plus', 'BIGVITA Scalp Serum+', 'BIGVITA', 'hair', 'physical', 'A leave-in, water-based scalp serum that comes as a box of three small bottles (1.02 fl oz in total) with a massaging applicator tip. BIGVITA says it contains 4% AnaGain (a pea sprout extract) plus centella, Biota orientalis leaf extract, biotin and niacinamide, and that it reduces shedding and supports thicker-looking hair. BIGVITA says each bottle lasts about 5 to 10 days, so a box lasts roughly 2 to 4 weeks. It is sold as a cosmetic.', '$39.00 for a box of three bottles (1.02 fl oz total) on bigvita.com and Amazon', 'https://m.media-amazon.com/images/I/51O7+TsgxZL._AC_SL500_.jpg', 'https://www.bigvita.com/products/scalp-serum', '["bigvita","scalp serum+","anagain","pea sprout","hair","scalp","hair serum","thinning","shedding","biotin","centella","cosmetic"]'::jsonb, '["skin-hair"]'::jsonb, '["bigvita.com","Amazon"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Sold as a cosmetic; not an FDA-approved drug for hair loss.","materials":"Three small bottles plus a massaging applicator tip. The second ingredient is alcohol, and it contains added fragrance (BIGVITA describes a \"citron noir\" scent). BIGVITA calls it clean, non-toxic and hormone-free; ayna did not independently verify those claims. BIGVITA says it is made in Canada.","recalls":"No recalls found.","sideEffects":"Per the H-E-B and Amazon listings: external use only, avoid contact with eyes. Contains alcohol and fragrance, so patch test first if you have a sensitive scalp.","opinionAlerts":"BIGVITA says AnaGain is \"clinically studied.\" The study ayna read applied a 2% pea sprout fluid to 10 volunteers and measured hair-related gene activity, not hair growth, and was run by the ingredient''s maker. The hair-loss result in that paper came from a pea sprout supplement taken by mouth, not a scalp serum."}'::jsonb, 'BIGVITA says 4% AnaGain is clinically studied to reactivate hair growth by shortening the resting phase and extending the growth phase, that centella improves scalp circulation, that Biota orientalis supports the growth cycle, and that the serum reduces shedding. No study of this product was found.

The main human study of pea sprout extract is a 2020 short report by researchers at Mibelle, the company that makes AnaGain. Applying a fluid with 2% pea sprout extract to the scalp of 10 volunteers raised the activity of two hair-related genes (FGF7 and noggin). That measured gene activity, not hair growth. In a separate pilot of 21 people, a 100 mg pea sprout supplement taken by mouth for 8 weeks reduced hair loss. A 2025 study found pea sprout extract supported hair growth signals in human hair cells and in mice. None of this tested a scalp serum for hair growth in people.

Centella has lab evidence only: in a 2017 study, a centella extract helped lab-grown human hair papilla cells. Biotin helps hair mainly in people who are deficient, according to a 2017 review of oral biotin. ayna did not read a study of Biota orientalis for hair loss in people; BIGVITA''s own page says more human studies are needed.

If you have thinning hair, a dermatologist can check for causes and discuss treatments with stronger evidence. Minoxidil is the over-the-counter hair-loss treatment the FDA has approved for women.', 'On bigvita.com it shows 4.69 out of 5 stars from 70 reviews (48 five-star and 22 four-star). On Amazon it has 3.7 out of 5 stars from 34 ratings; 53% are five stars and 18% are one star. Reviews on BIGVITA''s site include "less shedding and even some baby hairs growing in" and "noticed a slight change" after a week.', 'No study of this serum was found. Pea sprout extract has a small scalp study that measured gene activity, plus a small oral-supplement pilot, both from the ingredient''s maker.', 'brand', 'Product claims are sourced from BIGVITA; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"bigvita.com":"https://www.bigvita.com/products/scalp-serum","Amazon":"https://www.amazon.com/dp/B0D82212P3"},"ingredients":"Full ingredient list per H-E-B: Water/Aqua/Eau, Ethyl Alcohol, Butylene Glycol, Niacinamide, Pentylene Glycol, Allantoin, Centella Asiatica Leaf Extract, Pisum Sativum (Pea) Sprout Extract, Biotin, Biota Orientalis Leaf Extract, PEG-40, Hydrogenated Castor Oil, Betaine, Disodium EDTA, Fragrance/Parfum, Citric Acid, Phenoxyethanol, Ethylhexylglycerin. BIGVITA says the pea sprout extract (AnaGain) is at 4%.","doctorOpinionShort":"Pea sprout extract (AnaGain) has a 10-person scalp study that measured gene activity, not hair growth, run by the ingredient''s maker; its hair-loss result came from a supplement taken by mouth. Centella has lab evidence only. No study of this serum was found.","doctorOpinionCitations":[{"url":"https://www.bigvita.com/products/scalp-serum","label":"bigvita.com: Scalp Serum+, claims, FAQ and how to use"},{"url":"https://pubmed.ncbi.nlm.nih.gov/31680356/","label":"PubMed: Clinical evaluation of pea sprout extract in the treatment of hair loss (Phytother Res 2020)","chipLabel":"Pea sprout extract, 10 + 21 people (2020)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/41309367/","label":"PubMed: Pea sprout extract promotes hair follicle regeneration, cell and mouse study (J Microbiol Biotechnol 2025)","chipLabel":"Pea sprout cell and mouse study (2025)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/29032741/","label":"PubMed: Titrated extract of Centella asiatica in cultured human dermal papilla cells (Biosci Biotechnol Biochem 2017)","chipLabel":"Centella lab study (2017)"},{"url":"https://www.accessdata.fda.gov/scripts/cder/daf/index.cfm?event=overview.process&ApplNo=021812","label":"FDA (Drugs@FDA): NDA 021812, Women''s Rogaine 5% minoxidil foam, over-the-counter","chipLabel":"FDA: minoxidil for women"}],"whoItsFor":["People with shedding or thinning hair who want a light, non-greasy cosmetic scalp serum with a massaging tip","People comfortable with early-stage ingredient evidence","Not a substitute for seeing a dermatologist about new, sudden or patchy hair loss"],"howToUse":{"intro":"Per BIGVITA: use daily. A bottle lasts about 7 to 10 days with daily use.","steps":["Remove the cap from the serum bottle and attach the included applicator.","Apply the serum directly to your scalp.","Gently massage it in. No rinsing needed."],"sourceUrl":"https://www.bigvita.com/products/scalp-serum","sourceLabel":"bigvita.com: Scalp Serum+"},"warnings":["External use only; avoid contact with eyes (per the H-E-B listing).","Contains alcohol and added fragrance: patch test first if you have a sensitive scalp.","Already using minoxidil or another medicated hair-loss treatment: check with a healthcare professional before combining."],"ingredientScience":[{"name":"Pea sprout extract (AnaGain)","text":"BIGVITA says 4% AnaGain is clinically studied to shorten the resting phase and extend the growth phase. In a 2020 short report by Mibelle, AnaGain''s maker, a fluid with 2% pea sprout extract applied to a scalp zone of 10 volunteers raised the activity of two hair-related genes, FGF7 by 56% and noggin by 85%. That measured gene activity, not hair growth. A separate pilot in 21 people found a 100 mg daily pea sprout supplement taken by mouth reduced hair loss after 28 days. A 2025 study found pea sprout extract activated hair growth signaling in human hair papilla cells and in mice.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31680356/","label":"PubMed: Short communication, clinical evaluation of pea sprout extract in the treatment of hair loss (Grothe et al., Phytother Res 2020)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/41309367/","label":"PubMed: Pea sprout extract promotes hair follicle regeneration via anagen phase prolongation (Kim et al., J Microbiol Biotechnol 2025)"}]},{"name":"Centella asiatica","text":"BIGVITA says centella improves scalp circulation and nutrient delivery to follicles. In a 2017 lab study, a titrated centella extract increased the growth and size of human hair papilla cells grown as 3D spheres. It hasn''t been tested for hair loss in people in any study ayna read.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29032741/","label":"PubMed: Titrated extract of Centella asiatica increases hair inductive property in 3D spheroid cultured human dermal papilla cells (2017)"}]},{"name":"Biotin","text":"BIGVITA says biotin supports hair strength. A 2017 review of biotin for hair and nails found 18 reported cases where it helped, all in people with an underlying problem such as biotin deficiency, and concluded there isn''t enough evidence to support it in healthy people. The review covered biotin taken by mouth, not applied to the scalp.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28879195/","label":"PubMed: A review of the use of biotin for hair loss (Patel et al., Skin Appendage Disord 2017)"}]}],"scientificCitations":[{"url":"https://www.aad.org/public/diseases/hair-loss/types/female-pattern","text":"American Academy of Dermatology: Female pattern hair loss","summary":"The AAD says the FDA has approved 2% and 5% minoxidil as a non-prescription treatment for female pattern hair loss and calls it the most-recommended treatment. This is general guidance, not product-specific validation."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"amazon","url":"https://www.amazon.com/dp/B0D82212P3","text":"Amazon: BIGVITA Scalp Serum+ reviews","summary":"3.7 out of 5 stars from 34 ratings as of October 2026; 18% are one star."},{"platform":"website","url":"https://www.bigvita.com/products/scalp-serum","text":"bigvita.com: Scalp Serum+ customer reviews","summary":"4.69 out of 5 stars from 70 reviews on BIGVITA''s own site."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb)
